import { NextRequest, NextResponse } from 'next/server';
import { AppState, catById, compute, peso, pesoR, shortDate } from '@/lib/budget';
import { Lang, detectCategory, detectLang, extractAmount } from '@/lib/parseExpense';

interface AdviceRequest {
  state: AppState;
  history: { role: 'user' | 'assistant'; text: string }[];
  message: string;
}

const OLLAMA_HOST = process.env.OLLAMA_HOST || 'http://localhost:11434';
const OLLAMA_MODEL = process.env.OLLAMA_MODEL;

const CAT_TIPS: Record<string, { en: string; tl: string }> = {
  food: {
    en: 'Pack lunch 2-3 times a week, share viands with friends, and skip the daily milk tea.',
    tl: 'Magbaon ng lunch 2-3x a week, o mag-share ng ulam sa tropa. Iwas milk tea araw-araw.',
  },
  transpo: {
    en: 'Ride home with classmates, walk short distances, and take the jeep instead of Grab/Angkas when you can.',
    tl: 'Sumabay sa classmates pauwi, maglakad kung malapit lang, at iwas Grab/Angkas kung may jeep.',
  },
  school: {
    en: 'Photocopy borrowed books, print only what you really need, and buy supplies in bulk.',
    tl: 'Mag-photocopy na lang ng hiram na libro, i-print lang ang talagang kailangan, at bumili ng supplies nang maramihan.',
  },
  load: {
    en: 'Use school or piso WiFi, and pick longer promos instead of daily load.',
    tl: 'Mag-piso WiFi o school WiFi, at pumili ng mas mahabang promo kaysa daily na load.',
  },
  gala: {
    en: 'Set a weekly gala budget and look for free hangouts like parks or chilling at home.',
    tl: 'Mag-set ng gala budget per week, at hanapin ang libreng gala tulad ng park o tambay sa bahay.',
  },
  other: {
    en: 'Review your "Others" entries. Small leaks add up fast.',
    tl: 'I-review ang "Others" mo. Baka may maliliit na gastos na pwedeng iwasan.',
  },
};

function summarize(state: AppState) {
  const c = compute(state);
  const cats = c.byCat.map(x => `${x.label} ${pesoR(x.sum)} (${Math.round((x.sum / Math.max(1, c.spent)) * 100)}%)`).join(', ');
  return {
    c,
    text: [
      `Allowance: ${pesoR(state.budget)} from ${shortDate(state.start)} to ${shortDate(state.end)} (${c.total} days).`,
      `Day ${c.elapsed} of ${c.total}, ${c.left} days left.`,
      `Spent: ${pesoR(c.spent)} (${Math.round(c.pct)}%). Remaining: ${c.remaining < 0 ? '-' : ''}${pesoR(c.remaining)}.`,
      `Average spend per day: ${pesoR(c.avgPerDay)}. Safe spend per day from now: ${pesoR(c.perDay)}.`,
      `By category: ${cats || 'none yet'}.`,
    ].join('\n'),
  };
}

async function askOllama(context: string, history: AdviceRequest['history'], message: string, lang: Lang) {
  if (!OLLAMA_MODEL) return null;
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 45000);
  const langRule =
    lang === 'tl'
      ? 'The student wrote in Tagalog/Taglish, so reply in casual Taglish (mix of Filipino and English).'
      : 'The student wrote in English, so reply in clear, friendly English only. Do not use Tagalog.';
  try {
    const res = await fetch(`${OLLAMA_HOST}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: ctrl.signal,
      body: JSON.stringify({
        model: OLLAMA_MODEL,
        stream: false,
        messages: [
          {
            role: 'system',
            content:
              "You are Buddy, the student's friend who helps them handle their baon. Talk like a supportive kaibigan, warm and casual, not like a finance app or a tracker. " + langRule + ' ' +
              'Keep it short (2-5 sentences or a few bullet points), practical, and grounded in the numbers below. ' +
              'Use ₱ for money. Answer the question directly first. Never invent expenses or numbers that are not listed.\n\n' +
              'Student budget data:\n' + context,
          },
          ...history.slice(-8).map(m => ({ role: m.role, content: m.text })),
          { role: 'user', content: message },
        ],
      }),
    });
    if (!res.ok) return null;
    const data = await res.json();
    return (data?.message?.content as string)?.trim() || null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

function ruleReply(state: AppState, message: string, lang: Lang) {
  const { c } = summarize(state);
  const t = (en: string, tl: string) => (lang === 'tl' ? tl : en);
  const m = message.toLowerCase();
  const top = c.byCat[0];
  const amount = extractAmount(message);

  if (amount > 0 && /(bili|bilhin|buy|afford|kaya|purchase|get|worth|gastos ng)/.test(m)) {
    const after = c.remaining - amount;
    const perDayAfter = after > 0 && c.left > 0 ? after / c.left : 0;
    const tight = perDayAfter < c.avgPerDay * 0.7;
    if (after < 0) {
      return t(
        `Not right now. You'd be short by ${peso(-after)}. Wait for your next allowance or save up a little at a time.`,
        `Hindi kaya ngayon. Kulang ka ng ${peso(-after)}. Hintayin muna ang next allowance o mag-ipon nang paunti-unti.`,
      );
    }
    return t(
      `If you buy it (${peso(amount)}), you'll have ${peso(after)} left. Your safe spend drops from ${pesoR(c.perDay)} to ${pesoR(perDayAfter)} per day. ${tight ? "That's tight, so think it over." : 'You can handle it!'}`,
      `Kung bibilhin mo yan (${peso(amount)}), matitira ${peso(after)}. Bababa ang safe gastos mo from ${pesoR(c.perDay)} to ${pesoR(perDayAfter)} per day. ${tight ? 'Medyo hihigpit, pag-isipan muna.' : 'Kaya pa naman!'}`,
    );
  }

  if (/(ipon|save|saving|tipid|matira)/.test(m)) {
    const target = Math.max(0, Math.round(c.remaining * 0.2));
    const perDay = c.left > 0 ? (c.remaining - target) / c.left : 0;
    return t(
      `Try saving ${pesoR(target)} (20% of what's left). To get there, keep spending to ${pesoR(perDay)}/day.${top ? ` Easiest to cut: ${top.label}. ${CAT_TIPS[top.id].en}` : ''}`,
      `Try mo mag-target ng ${pesoR(target)} ipon (20% ng natitira). Para makuha yan, gastos ka lang ng ${pesoR(perDay)}/day.${top ? ` Pinakamadaling bawasan: ${top.label}. ${CAT_TIPS[top.id].tl}` : ''}`,
    );
  }

  if (/(saan|where|category|categories|pinakamalaki|biggest|top|breakdown|napupunta|going)/.test(m)) {
    if (!c.byCat.length) return t('No spending this period yet, so there is no breakdown.', 'Wala ka pang gastos this period, kaya wala pang breakdown.');
    return t('Here is where your money goes:\n', 'Breakdown ng gastos mo:\n') +
      c.byCat.map(x => `• ${x.label}: ${pesoR(x.sum)} (${Math.round((x.sum / c.spent) * 100)}%)`).join('\n');
  }

  const cat = detectCategory(m);
  if (cat !== 'other' || /\b(others?|misc)\b/.test(m)) {
    return t(`Tips for ${catById(cat).label}: ${CAT_TIPS[cat].en}`, `Tips para sa ${catById(cat).label}: ${CAT_TIPS[cat].tl}`);
  }

  if (/(tip|bawas|cut|reduce|paano|how|advice|payo|help)/.test(m)) {
    if (!top) return t('No data yet. Log a few expenses first so I can give you specific tips.', 'Wala pang data. Mag-log ka muna ng ilang gastos para makapagbigay ako ng specific na tips.');
    return t(
      `Your biggest spending is ${top.label} (${pesoR(top.sum)}). ${CAT_TIPS[top.id].en} Cutting it by 30% saves you ${pesoR(top.sum * 0.3)}.`,
      `Pinakamalaki mong gastos ay ${top.label} (${pesoR(top.sum)}). ${CAT_TIPS[top.id].tl} Kung mabawasan mo ito ng 30%, makakatipid ka ng ${pesoR(top.sum * 0.3)}.`,
    );
  }

  return t(
    `You've spent ${pesoR(c.spent)} (${Math.round(c.pct)}%) and ${c.remaining < 0 ? `you're ${pesoR(-c.remaining)} over budget` : `have ${pesoR(c.remaining)} left for ${c.left} days`}. Safe spend: ${pesoR(c.perDay)}/day.${top ? ` Keep an eye on ${top.label}.` : ''}`,
    `${c.st.title}. Nagastos ka na ng ${pesoR(c.spent)} (${Math.round(c.pct)}%) at ${c.remaining < 0 ? `lampas ka ng ${pesoR(-c.remaining)}` : `may ${pesoR(c.remaining)} pa for ${c.left} days`}. Safe gastos: ${pesoR(c.perDay)}/day.${top ? ` Bantayan ang ${top.label}.` : ''}`,
  );
}

export async function POST(req: NextRequest) {
  try {
    const { state, history = [], message }: AdviceRequest = await req.json();
    if (!message || !state) return NextResponse.json({ error: 'missing input' }, { status: 400 });

    const lang = detectLang(message);
    const { text } = summarize(state);
    const fallback = ruleReply(state, message, lang);
    // The rule-based answer gives the model correct math to build on
    const ai = await askOllama(`${text}\n\nComputed analysis for this question (numbers are correct, reuse them):\n${fallback}`, history, message, lang);
    if (ai) return NextResponse.json({ reply: ai, source: 'ai', lang });

    return NextResponse.json({ reply: fallback, source: 'rules', lang });
  } catch {
    return NextResponse.json({ reply: 'Something went wrong, please try again.', source: 'rules', lang: 'en' });
  }
}
